--
-- Структура таблицы `facility`
--

CREATE TABLE `facility` (
  `id` int(11) NOT NULL,
  `address_id` int(11) NOT NULL,
  `company_id` int(11) DEFAULT NULL,
  `title` varchar(255) NOT NULL,
  `short_title` varchar(255) NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `approach` text DEFAULT NULL,
  `date_from` date DEFAULT NULL,
  `date_to` date DEFAULT NULL,
  `active` tinyint(1) NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Дамп данных таблицы `facility`
--

INSERT INTO `facility` (`id`, `address_id`, `company_id`, `title`, `short_title`, `description`, `approach`, `date_from`, `date_to`, `active`) VALUES
(3, 71, 2, 'Standort Zirkus', 'ZRK', NULL, 'Mit dem Auto:\n- Navi: Hauptstraße 2, 10001 Musterstadt\n- Über Stadtautobahn Ausfahrt Mitte, Richtung Zentrum, links in die Hauptstraße.\n- Parkplätze direkt am Objekt vorhanden.\n\nÖPNV:\n- Straßenbahn 3 oder 7 bis \"Stadtmitte\", dann 2 Min. zu Fuß.\n- Bus 42 bis \"Hauptstraße\".', '2025-11-24', '2025-11-25', 0),
(4, 92, 5, 'Baustelle Industrie Süd', 'BIS', NULL, 'Mit dem Auto:\n- Navi: Lindenstraße 184, 10001 Musterstadt\n- Einfahrt gegenüber Haltestelle \"Industriepark Süd\", Tor 2.\n- Von Stadtautobahn: Ausfahrt Nord → B97 Richtung Gewerbegebiet.\n\nÖPNV:\n- Bus 64 bis \"Industriepark\", dann 5 Min. zu Fuß.', '2025-11-20', '2025-11-22', 0),
(5, 78, 6, 'Demo-Center Mitte', 'DCM', NULL, 'Mit dem Auto:\n- Navi: Kirchstraße 2a, 10001 Musterstadt\n- Objekt liegt in der Stadtmitte nahe Bahnhof.\n- Parken in Seitenstraßen oder im Parkhaus nebenan.\n\nÖPNV:\n- Tram 1, 3 oder Bus 62 bis \"Stadtmitte Süd\", dann 3 Min. zu Fuß.', '2025-11-28', '2026-11-28', 0),
(7, 44, 3, 'Brandwache Hochhaus', 'BWH', NULL, 'Mit dem Auto:\n- Navi: Gartenstraße 5, 10001 Musterstadt\n- Über Ringstraße → Gartenstraße.\n- Parkplätze an der Straße (teils kostenpflichtig).\n\nÖPNV:\n- Straßenbahn 1, 2, 4 oder Bus 75 bis \"Gartenplatz\", dann 2 Min. zu Fuß.', '2025-12-16', '2026-02-28', 0),
(9, 77, 8, 'Büro Zentrale', 'BZL', NULL, 'Mit dem Auto:\n- Navi: Waldstraße 20, 10001 Musterstadt\n- Gewerbegebiet, westliche Waldstraße. Von B170 / Ausfahrt Süd → Waldstraße.\n- Firmenparkplatz direkt am Gebäude.\n\nÖPNV:\n- Bus 85 bis \"Waldstraße\", dann 1 Min. zu Fuß.', '2026-01-01', '2035-01-15', 1),
(10, 48, 1, 'Revierstreife Einkaufszentrum', 'REZ', NULL, 'Mit dem Auto:\n- Navi: Ringstraße 96, 10001 Musterstadt\n- Revierfahrzeug startet am Parkplatz Ringstraße, Eingang Süd.\n\nÖPNV:\n- Tram 6 bis \"Ringplatz\", dann 4 Min. zu Fuß.', '2024-01-01', '2027-01-31', 1),
(11, 49, 3, 'Klinik Standort A4', 'KSA4', NULL, 'Mit dem Auto:\n- Navi: Industrieweg 23, 10001 Musterstadt\n- Von A4: Ausfahrt Süd → Richtung Klinikum, Beschilderung \"Klinik A\" folgen.\n- Besucherparkplatz am Nebeneingang.\n\nÖPNV:\n- Bus 66 bis \"Klinikum Süd\", dann 3 Min. zu Fuß.', '2024-01-25', '2027-01-31', 1),
(12, 98, 3, 'Hotel Dresden', 'HTD', NULL, 'Mit dem Auto:\n- Navi: Marktstraße 2c, 10001 Musterstadt\n- Über B170 Richtung Innenstadt, Ausfahrt Zentrum/Marktstraße.\n- Parkhäuser in unmittelbarer Nähe.\n\nÖPNV:\n- Tram oder Bus bis \"Marktstraße\", dann 2 Min. zu Fuß.', '2026-01-05', '2026-04-05', 0),
(13, 82, 3, 'Asylbewerberheim Nord', 'ABN', NULL, 'Mit dem Auto:\n- Navi: Landstraße 52a, 70001 Musterdorf West\n- Von A4: Ausfahrt Musterdorf West → L177 / Landstraße, Ziel rechts.\n- Parken entlang der Straße bzw. auf dem Gelände.\n\nÖPNV:\n- Bus 303 bis \"Landstraße Mitte\", dann 5 Min. zu Fuß.', '2024-01-01', '2026-06-30', 1),
(14, 67, 3, 'Revierstreife Ost', 'RSO', NULL, 'Mit dem Auto:\n- Navi: Gartenstraße 15a, 10001 Musterstadt\n- Revierfahrzeug startet am Parkplatz Gartenstraße. Kostenlos vor Ort.\n\nÖPNV:\n- Bus 45 bis \"Gartenstraße\", dann 2 Min. zu Fuß.', '2024-01-01', '2026-12-31', 1),
(15, 72, 1, 'Kaufhaus Zentrum', 'KZT', NULL, 'Mit dem Auto:\n- Navi: Schulstraße 5, 80001 Musterdorf Nord\n- Über B7 → Ausfahrt Musterdorf Nord → Schulstraße.\n- Kundenparkplätze direkt am Gebäude.\n\nÖPNV:\n- Bus 12 bis \"Schulstraße\", dann 3 Min. zu Fuß.', '2024-01-01', '2026-12-31', 0),
(16, 73, 4, 'Krankenhaus Ost', 'KHO', NULL, 'Mit dem Auto:\n- Navi: Stadtstraße 3, 30001 Musterstadt Ost\n- Von A4: Ausfahrt Ost → Klinikum Ost, Beschilderung folgen.\n- Besucherparkplatz auf dem Klinikgelände.\n\nÖPNV:\n- Bus 88 bis \"Krankenhaus Ost Eingang\", dann 1 Min. zu Fuß.', '2024-12-01', '2026-12-31', 0),
(17, 74, 4, 'Medienanstalt Dresden', 'MAD', NULL, 'Mit dem Auto:\n- Navi: Kirchstraße 11, 10001 Musterstadt\n- Über Hauptstraße → Kirchstraße, Objekt links.\n- Parkplätze im Innenhof (Code beim Empfang).\n\nÖPNV:\n- Tram 2 oder Bus 68 bis \"Kirchplatz\", dann 2 Min. zu Fuß.', '2024-01-01', '2026-12-31', 0),
(18, 75, 1, 'Asylbewerberheim Süd', 'ABS', NULL, 'Mit dem Auto:\n- Navi: Allee 40, 10001 Musterstadt\n- Von der Ringstraße → Allee, Objekt am Ende rechts.\n- Parkplätze auf dem Gelände.\n\nÖPNV:\n- Bus 31 bis \"Allee Mitte\", dann 5 Min. zu Fuß.', '2024-01-01', '2026-12-31', 1),
(19, 76, 3, 'Wohnanlage Mitte', 'WAM', NULL, 'Mit dem Auto:\n- Navi: Marktstraße 15, 10001 Musterstadt\n- Über Innenstadt → Marktstraße, Eingang über Seitenstraße.\n- Tiefgarage im Gebäude (Einfahrt Rückseite).\n\nÖPNV:\n- Tram 4 oder Bus 62 bis \"Marktstraße Süd\", dann 2 Min. zu Fuß.', '2024-01-01', '2026-12-31', 0),
(20, 83, 3, 'Klinik Standort A1', 'KSA1', NULL, 'Mit dem Auto:\n- Navi: Klosterstraße 1, 50001 Musterdorf\n- Von A4: Ausfahrt Musterdorf → Klinikum A1, Beschilderung folgen.\n- Besucherparkplatz am Haupteingang.\n\nÖPNV:\n- Bus 66 bis \"Klinikum Musterdorf\", dann 3 Min. zu Fuß.', '2024-01-01', '2026-12-31', 1),
(21, 84, 3, 'Standort Heidenau', 'STH', NULL, 'Mit dem Auto:\n- Navi: Bahnhofstraße 8, 60001 Musterdorf Süd\n- Von B172: Ausfahrt Musterdorf Süd → Bahnhofstraße, direkt am Bahnhof.\n- Kostenlose Parkplätze vor dem Gebäude.\n\nÖPNV:\n- S-Bahn bis \"Musterdorf Süd Bahnhof\", dann 1 Min. zu Fuß.', '2025-05-01', '2026-12-31', 1),
(22, 89, 9, 'Handelszentrum Dresden', 'HZD', NULL, 'Mit dem Auto:\n- Navi: Platz der Einheit 3, 10001 Musterstadt\n- Über Innenstadt, Ausfahrt Zentrum → Platz der Einheit.\n- Parkhäuser in unmittelbarer Umgebung.\n\nÖPNV:\n- Tram 7, 8 oder Bus 62, 75 bis \"Platz der Einheit\", dann 1 Min. zu Fuß.', '2024-10-28', '2026-12-31', 0),
(23, 90, 3, 'Friedhof Projekt', 'FPR', NULL, 'Mit dem Auto:\n- Navi: Landstraße 299, 10001 Musterstadt\n- Von Stadtautobahn → Ausfahrt Nord → Landstraße, Einfahrt Nebentor.\n- Parkplätze auf dem Gelände.\n\nÖPNV:\n- Bus 30 bis \"Landstraße Eingang\", dann 5 Min. zu Fuß.', '2026-02-12', '2026-02-14', 0),
(24, 94, 3, 'Revierstreife Stadtmitte', 'RSM', NULL, 'Mit dem Auto:\n- Navi: Marktstraße 5, 10001 Musterstadt\n- Revierfahrzeug startet Parkplatz Marktstraße Süd. Eingang Westseite.\n\nÖPNV:\n- Tram 3 oder Bus 80 bis \"Stadtmitte West\", dann 3 Min. zu Fuß.', '2026-02-28', '2026-03-14', 0),
(25, 99, 3, 'Brandwache Gebäude', 'BWG', NULL, 'Mit dem Auto:\n- Navi: Kirchstraße 11, 10001 Musterstadt\n- Brandwache: Eingang Süd, Klingel beim Empfang.\n- Innenhof-Parkplatz (Tor bleibt während der Wache offen).\n\nÖPNV:\n- Bus 68 bis \"Kirchstraße\", dann 2 Min. zu Fuß.', '2026-03-23', '2026-05-04', 1),
(26, 96, 1, 'Messe Standort', 'MSS', NULL, 'Mit dem Auto:\n- Navi: Ringstraße 1, 10001 Musterstadt\n- Von A4: Ausfahrt Mitte → Messegelände, Beschilderung \"Messe\" folgen.\n- Messeparkplatz P1 (kostenpflichtig bei Veranstaltungen).\n\nÖPNV:\n- Tram 6 oder Bus 80 bis \"Messering\", dann 5 Min. zu Fuß.', '2026-03-25', NULL, 1),
(27, 100, 3, 'Hotel Standort', 'HST', NULL, 'Mit dem Auto:\n- Navi: Bahnhofstraße 12, 10001 Musterstadt\n- Über Innenstadt → Bahnhofstraße, Hoteleinfahrt rechts.\n- Hotelparkplatz im Innenhof (Code vom Empfang).\n\nÖPNV:\n- Tram 1, 4 oder Bus 62 bis \"Hauptbahnhof\", dann 3 Min. zu Fuß.', '2026-05-04', '2026-05-20', 1);

